import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [success, setSuccess] = useState<string | null>(null);

  const emailValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !emailValid ? 'Введите адрес вида name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!emailValid) {
      setTouched(true);
      return;
    }
    const roleLabel = ROLES.find((item) => item.value === role)?.label ?? role;
    setSuccess(
      `Приглашение для ${email.trim()} отправлено. Роль: ${roleLabel}.` +
        (notify ? ' Уведомление на почту отправлено.' : ''),
    );
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}
    >
      {success && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <span>{success}</span>
            <div>
              <JxButton variant="ghost" size="sm" type="button" onClick={() => setSuccess(null)}>
                Закрыть
              </JxButton>
            </div>
          </div>
        </JxAlert>
      )}

      <JxInputField
        label="Электронная почта"
        type="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Приглашение придёт на этот адрес"
        errorText={errorText}
      />

      <JxSelect
        label="Роль в команде"
        placeholder="Выберите роль"
        options={ROLES}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        label="Отправить уведомление на почту"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <div>
        <JxButton variant="primary" type="submit" disabled={!emailValid}>
          Отправить приглашение
        </JxButton>
      </div>
    </form>
  );
}

